<script setup>
import { ref, onMounted, watch } from 'vue';
import axios from 'axios';
import AppLayout from '@/Layouts/AppLayout.vue';
import PrimaryButton from '@/Components/PrimaryButton.vue';
import ConfirmationModal from '@/Components/ConfirmationModal.vue';
const props=defineProps({clientId:Number});
const clientId=ref(props.clientId||'');const typeId=ref('');const date=ref(new Date(Date.now()+86400000).toISOString().slice(0,10));const notes=ref('');const search=ref('');
const options=ref(null);const slots=ref([]);const searched=ref(false);const busy=ref(false);const error=ref('');const success=ref('');const chosen=ref(null);const appointment=ref(null);
function fail(e){error.value=Object.values(e.response?.data?.errors??{}).flat().join(' ')||e.response?.data?.message||'Operazione non riuscita. Riprova.';}
async function load(page=1,appointmentPage=1){busy.value=true;error.value='';try{options.value=(await axios.get(route('booking.options'),{params:{q:search.value||undefined,client_profile_id:clientId.value||undefined,page,appointment_page:appointmentPage}})).data.data;if(!clientId.value&&options.value.clients.total===1){clientId.value=options.value.clients.data[0].id;}}catch(e){fail(e);}finally{busy.value=false;}}
watch(clientId,()=>{appointment.value=null;slots.value=[];searched.value=false;load();});watch([typeId,date],()=>{slots.value=[];searched.value=false;});onMounted(()=>load());
async function find(){busy.value=true;error.value='';success.value='';chosen.value=null;try{slots.value=(await axios.get(route('booking.slots'),{params:{client_profile_id:clientId.value,practice_type_id:typeId.value,date:date.value,appointment_id:appointment.value?.id}})).data.data;searched.value=true;}catch(e){fail(e);}finally{busy.value=false;}}
async function book(){busy.value=true;error.value='';try{const response=await axios.post(appointment.value?route('booking.reschedule',appointment.value.id):route('booking.store'),{slot:chosen.value.token,notes:notes.value||null});success.value=`${appointment.value?'Appuntamento riprogrammato':'Appuntamento prenotato'} per ${new Date(response.data.data.scheduled_at).toLocaleString('it-IT')}. Stato: ${response.data.data.status==='confermato'?'confermato':'in attesa di conferma dello studio'}.`;chosen.value=null;appointment.value=null;notes.value='';slots.value=[];searched.value=false;await load();}catch(e){chosen.value=null;slots.value=[];searched.value=false;fail(e);}finally{busy.value=false;}}
function reschedule(item){appointment.value=item;typeId.value=item.practice_type_id;slots.value=[];searched.value=false;success.value='';}
</script>
<template><AppLayout title="Prenota un orario disponibile"><template #header><h2 class="text-xl font-semibold text-gray-800 dark:text-gray-100">Prenota un orario disponibile</h2></template><div class="mx-auto max-w-5xl space-y-6 px-4 py-8 sm:px-6 dark:text-gray-100"><p class="text-sm text-gray-600 dark:text-gray-300">Gli orari tengono conto della disponibilità degli operatori e degli appuntamenti già prenotati. Il controllo viene ripetuto al salvataggio.</p><p v-if="error" role="alert" class="rounded-xl bg-red-50 p-4 text-red-800">{{error}}</p><p v-if="success" role="status" class="rounded-xl bg-green-50 p-4 text-green-800">{{success}}</p>
<section class="space-y-4 rounded-2xl border bg-white p-5 dark:border-gray-700 dark:bg-gray-800"><h3 class="text-lg font-semibold">Per chi vuoi prenotare?</h3><form @submit.prevent="load(1)" class="flex flex-wrap gap-3"><label class="flex-1"><span class="sr-only">Cerca un profilo</span><input v-model="search" placeholder="Cerca un profilo per nome" maxlength="100" class="w-full rounded-xl border-gray-300 dark:bg-gray-900" /></label><PrimaryButton :disabled="busy">Cerca profilo</PrimaryButton></form><label class="block text-sm">Profilo<select v-model="clientId" :disabled="busy" class="mt-2 block w-full rounded-xl border-gray-300 dark:bg-gray-900"><option value="">Seleziona un profilo</option><option v-if="options?.client&&!options.clients.data.some(c=>c.id===options.client.id)" :value="options.client.id">{{options.client.first_name}} {{options.client.last_name}}</option><option v-for="client in options?.clients.data||[]" :key="client.id" :value="client.id">{{client.first_name}} {{client.last_name}}</option></select></label><div v-if="options?.clients.last_page>1" class="flex justify-between"><button :disabled="busy||options.clients.current_page===1" @click="load(options.clients.current_page-1)" class="app-button min-h-12 px-4">Precedenti profili</button><span>{{options.clients.current_page}} / {{options.clients.last_page}}</span><button :disabled="busy||options.clients.current_page===options.clients.last_page" @click="load(options.clients.current_page+1)" class="app-button min-h-12 px-4">Altri profili</button></div><p v-if="options&&!options.clients.total">Nessun profilo disponibile per la prenotazione.</p></section>
<form v-if="clientId" @submit.prevent="find" class="space-y-4 rounded-2xl border bg-white p-5 dark:border-gray-700 dark:bg-gray-800"><div v-if="appointment" class="rounded-xl bg-amber-50 p-4 text-amber-900">Stai riprogrammando l’appuntamento del {{new Date(appointment.scheduled_at).toLocaleString('it-IT')}}.<button type="button" @click="appointment=null;slots=[]" class="app-button ml-3 min-h-12 underline">Annulla riprogrammazione</button></div><label class="block text-sm">Prestazione<select v-model="typeId" required :disabled="busy||!!appointment" class="mt-2 block w-full rounded-xl border-gray-300 dark:bg-gray-900"><option value="">Seleziona una prestazione</option><option v-for="type in options?.practice_types||[]" :key="type.id" :value="type.id">{{type.name}} · {{type.duration_minutes}} minuti</option></select></label><label class="block text-sm">Giorno<input v-model="date" required type="date" :min="new Date().toISOString().slice(0,10)" :max="new Date(Date.now()+90*86400000).toISOString().slice(0,10)" class="mt-2 block rounded-xl border-gray-300 dark:bg-gray-900" /></label><label class="block text-sm">Note (facoltative)<textarea v-model="notes" maxlength="1000" rows="3" class="mt-2 block w-full rounded-xl border-gray-300 dark:bg-gray-900" /></label><PrimaryButton :disabled="busy||!typeId">Cerca orari disponibili</PrimaryButton></form>
<section v-if="searched" class="space-y-4 rounded-2xl border bg-white p-5 dark:border-gray-700 dark:bg-gray-800"><h3 class="text-lg font-semibold">Orari disponibili</h3><p v-if="!slots.length">Nessun orario disponibile. Prova un altro giorno.</p><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><button v-for="slot in slots" :key="slot.token" :disabled="busy" @click="chosen=slot" class="min-h-16 rounded-xl border border-blue-300 p-4 text-left hover:bg-blue-50 dark:hover:bg-gray-900"><strong>{{new Date(slot.scheduled_at).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}} · {{slot.duration_minutes}} min</strong><span class="mt-1 block text-sm">{{slot.operator.name}}</span></button></div><p class="text-sm text-gray-500">L’elenco scade dopo 15 minuti. La prenotazione viene registrata solo dopo la conferma.</p></section>
<section v-if="options?.appointments" class="space-y-4 rounded-2xl border bg-white p-5 dark:border-gray-700 dark:bg-gray-800"><h3 class="text-lg font-semibold">Appuntamenti futuri del profilo</h3><p v-if="!options.appointments.total">Nessun appuntamento futuro.</p><article v-for="item in options.appointments.data" :key="item.id" class="flex flex-wrap items-center justify-between gap-4 border-t py-4"><div><strong>{{item.practice_type?.name}}</strong><p>{{new Date(item.scheduled_at).toLocaleString('it-IT')}}</p></div><button :disabled="busy" @click="reschedule(item)" class="app-button min-h-12 rounded-lg border px-4">Scegli un altro orario</button></article><div v-if="options.appointments.last_page>1" class="flex justify-between"><button :disabled="busy||options.appointments.current_page===1" @click="load(1,options.appointments.current_page-1)" class="app-button min-h-12 px-4">Precedenti</button><span>{{options.appointments.current_page}} / {{options.appointments.last_page}}</span><button :disabled="busy||options.appointments.current_page===options.appointments.last_page" @click="load(1,options.appointments.current_page+1)" class="app-button min-h-12 px-4">Successivi</button></div></section></div>
<ConfirmationModal :show="!!chosen" @close="!busy&&(chosen=null)"><template #title>{{appointment?'Conferma il nuovo orario':'Conferma prenotazione'}}</template><template #content><p v-if="chosen">{{new Date(chosen.scheduled_at).toLocaleString('it-IT')}} · {{chosen.duration_minutes}} minuti · {{chosen.operator.name}}</p></template><template #footer><button :disabled="busy" @click="chosen=null" class="app-button min-h-12 px-4">Annulla</button><PrimaryButton :disabled="busy" @click="book">{{busy?'Salvataggio…':'Conferma'}}</PrimaryButton></template></ConfirmationModal></AppLayout></template>
